import 'dart:convert';
import 'dart:typed_data';

/// Textura fotorrealista embutida em Base64 do módulo fotovoltaico half-cell azul cristalino.
/// Garante carregamento instantâneo no Flutter Web sem depender de reinicialização do servidor de assets.
abstract class SolarPanelTextureData {
  static const String base64Webp = '';

  static Uint8List get bytes => base64Decode(base64Webp);
}
